import numpy as np
from sklearn.svm import SVC


class QuantumKernel:
    """Quantum kernel for classical machine learning via quantum feature maps."""

    def __init__(self, n_qubits):
        self.n_qubits = n_qubits
        self.dim = 2 ** n_qubits

    def _rz(self, theta):
        return np.array([
            [np.exp(-1j * theta / 2), 0],
            [0, np.exp(1j * theta / 2)]
        ], dtype=complex)

    def _ry(self, theta):
        return np.array([
            [np.cos(theta / 2), -np.sin(theta / 2)],
            [np.sin(theta / 2), np.cos(theta / 2)]
        ], dtype=complex)

    def _single_qubit_gate(self, gate, qubit):
        full_op = np.array([[1]], dtype=complex)
        for q in range(self.n_qubits):
            if q == qubit:
                full_op = np.kron(full_op, gate)
            else:
                full_op = np.kron(full_op, np.eye(2, dtype=complex))
        return full_op

    def _apply_cnot(self, state, control, target):
        cnot = np.zeros((self.dim, self.dim), dtype=complex)
        for i in range(self.dim):
            control_bit = (i >> (self.n_qubits - 1 - control)) & 1
            if control_bit == 1:
                j = i ^ (1 << (self.n_qubits - 1 - target))
                cnot[j, i] = 1.0
            else:
                cnot[i, i] = 1.0
        return cnot @ state

    def encode_data(self, x):
        """Encode classical data into quantum state."""
        state = np.zeros(self.dim, dtype=complex)
        state[0] = 1.0

        for q in range(min(self.n_qubits, len(x))):
            ry_gate = self._ry(x[q] * np.pi)
            full_op = self._single_qubit_gate(ry_gate, q)
            state = full_op @ state

        for q in range(self.n_qubits - 1):
            state = self._apply_cnot(state, q, q + 1)

        for q in range(min(self.n_qubits, len(x))):
            rz_gate = self._rz(x[q] * np.pi)
            full_op = self._single_qubit_gate(rz_gate, q)
            state = full_op @ state

        return state

    def kernel_function(self, x1, x2):
        """Compute quantum kernel: |<phi(x1)|phi(x2)>|^2."""
        state1 = self.encode_data(x1)
        state2 = self.encode_data(x2)

        overlap = np.abs(np.dot(state1.conj(), state2)) ** 2
        return overlap

    def compute_kernel_matrix(self, X):
        """Compute full kernel matrix for dataset X."""
        n_samples = X.shape[0]
        K = np.zeros((n_samples, n_samples))

        for i in range(n_samples):
            for j in range(i, n_samples):
                K[i, j] = self.kernel_function(X[i], X[j])
                K[j, i] = K[i, j]

        return K

    def train_svm(self, X, y, C=1.0):
        """Train SVM with quantum kernel."""
        K = self.compute_kernel_matrix(X)

        svm = SVC(kernel='precomputed', C=C)
        svm.fit(K, y)
        return svm

    def predict(self, svm, X_train, X_test):
        """Predict using trained SVM with quantum kernel."""
        n_test = X_test.shape[0]
        n_train = X_train.shape[0]
        K_test = np.zeros((n_test, n_train))

        for i in range(n_test):
            for j in range(n_train):
                K_test[i, j] = self.kernel_function(X_test[i], X_train[j])

        return svm.predict(K_test)


if __name__ == "__main__":
    np.random.seed(42)
    qk = QuantumKernel(n_qubits=2)

    X = np.array([[0.1, 0.2], [0.8, 0.9], [0.2, 0.1], [0.9, 0.8]])
    y = np.array([0, 1, 0, 1])

    K = qk.compute_kernel_matrix(X)
    print("Kernel matrix:")
    print(np.round(K, 3))

    svm = qk.train_svm(X, y, C=1.0)
    predictions = qk.predict(svm, X, X)
    print(f"\nPredictions: {predictions}")
    print(f"Accuracy: {np.mean(predictions == y):.2%}")
